{
  "questions": [
    {
      "n": 1,
      "start": "Pourquoi cette information est-elle transmise si tardivement",
      "end": "alors que le plan de réorganisation est validé depuis 2014 et que le regroupement de l'activité opératoire est prévue pour 2027 ?"
    },
    {
      "n": 2,
      "start": "Pourrions-nous avoir des détails quant à ce chiffre avancé de 3 millions d'économie ?",
      "end": "Comment cela a-t-il été calculé ?"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Am 20. August 2025 bestätigte der Staatsrat den 2014 gefassten Entscheid,",
      "end": "die operative Tätigkeit des Spitalzentrums des französischsprachigen Wallis (CHVR) am Standort Sion zusammenzufassen."
    },
    {
      "n": 2,
      "start": "Die in Ihrer Interpellation genannten Einsparungen in Höhe von 3 Millionen pro Jahr",
      "end": "sind das Ergebnis einer ersten Schätzung des Spital Wallis, die auf einer französischen Studie über den Betrieb von 1'400 Operationssälen basiert."
    }
  ],
  "submitter": "Aida Lips, Marie-Bertrande Duay et Julien Besson",
  "co_signatories": ["Marie-Bertrande Duay", "Julien Besson"],
  "recommendation": "none",
  "reasoning": {
    "start": "Die Zusammenlegung der operativen Tätigkeit in Sitten ist aus medizinischen und wirtschaftlichen Gründen gerechtfertigt.",
    "end": "Diese Spezialisierung ist unerlässlich, um eine effiziente und qualitativ hochwertige Versorgung zu gewährleisten."
  }
}
